172:<INSTR>{

<INITIAL>^[[:blank:]]*Defaults([:@>\!][[:blank:]]*\!*\"?({ID}|{WORD}))? {
                            char deftype;
                            int n;

                            if (continued) {
                                sudoerserror(N_("invalid line continuation"));
                                LEXTRACE("ERROR ");
                                return ERROR;
                            }

                            for (n = 0; isblank((unsigned char)sudoerstext[n]); n++)
                                continue;
                            n += sizeof("Defaults") - 1;
                            if ((deftype = sudoerstext[n++]) != '\0') {
                                while (isblank((unsigned char)sudoerstext[n]))
                                    n++;
                            }
                            BEGIN GOTDEFS;
                            switch (deftype) {
                                case ':':
                                    sudoersless(n);
                                    LEXTRACE("DEFAULTS_USER ");
                                    return DEFAULTS_USER;
                                case '>':
                                    sudoersless(n);
                                    LEXTRACE("DEFAULTS_RUNAS ");
                                    return DEFAULTS_RUNAS;
                                case '@':
                                    sudoersless(n);
                                    LEXTRACE("DEFAULTS_HOST ");
                                    return DEFAULTS_HOST;
                                case '!':
                                    sudoersless(n);
                                    LEXTRACE("DEFAULTS_CMND ");
                                    return DEFAULTS_CMND;
                                default:
                                    LEXTRACE("DEFAULTS ");
                                    return DEFAULTS;
                            }
                        }

<INITIAL>^[[:blank:]]*(Host|Cmnd|Cmd|User|Runas)_Alias  {
                            int n;

                            if (continued) {
                                sudoerserror(N_("invalid line continuation"));
                                LEXTRACE("ERROR ");
                                return ERROR;
                            }

                            for (n = 0; isblank((unsigned char)sudoerstext[n]); n++)
                                continue;
                            switch (sudoerstext[n]) {
                                case 'H':
                                    LEXTRACE("HOSTALIAS ");
                                    return HOSTALIAS;
                                case 'C':
                                    LEXTRACE("CMNDALIAS ");
                                    return CMNDALIAS;
                                case 'U':
                                    LEXTRACE("USERALIAS ");
                                    return USERALIAS;
                                case 'R':
                                    LEXTRACE("RUNASALIAS ");
                                    return RUNASALIAS;
                            }
                        }

NOPASSWD[[:blank:]]*:   {
                                /* cmnd does not require passwd for this user */
                                LEXTRACE("NOPASSWD ");
                                return NOPASSWD;
                        }

PASSWD[[:blank:]]*:     {
                                /* cmnd requires passwd for this user */
                                LEXTRACE("PASSWD ");
                                return PASSWD;
                        }

NOEXEC[[:blank:]]*:     {
                                LEXTRACE("NOEXEC ");
                                return NOEXEC;
                        }

EXEC[[:blank:]]*:       {
                                LEXTRACE("EXEC ");
                                return EXEC;
                        }

SETENV[[:blank:]]*:     {
                                LEXTRACE("SETENV ");
                                return SETENV;
                        }

NOSETENV[[:blank:]]*:   {
                                LEXTRACE("NOSETENV ");
                                return NOSETENV;
                        }
